function renderIndicators(){const c=calc();$('#sumIncome').textContent=brl(c.income);$('#sumExpense').textContent=brl(c.fixed+c.variable);$('#sumSaving').textContent=brl(c.saldo);$('#sumSaving').className=c.saldo>=0?'positive':'negative';const groups=Object.keys(state.goals);$('#bars').innerHTML=groups.map(g=>{const val=currentTx().filter(t=>t.tipo==='despesa'&&t.recorrencia==='variavel'&&t.categoria===g).reduce((s,t)=>s+t.valor,0),goal=c.available*state.goals[g]/100,pct=goal?val/goal*100:0;return `<div class="barrow"><div class="bartop"><span>${g}</span><b class="${pct>100?'negative':''}">${brl(val)} / ${brl(goal)}</b></div><div class="bar"><span class="${pct>100?'over':''}" style="width:${Math.min(100,pct)}%"></span></div></div>`}).join('')}
