function applyHistory(){const q=$('#histQuery').value.toLowerCase(),m=$('#histMonth').value,c=$('#histCat').value;const list=[...state.transactions].filter(t=>(!q||(t.descricao||'').toLowerCase().includes(q))&&(!m||monthKey(t.data)===m)&&(!c||t.categoria===c)).sort((a,b)=>b.data.localeCompare(a.data));$('#histCount').textContent=`${list.length} lançamentos`;$('#histTotal').textContent=brl(list.filter(x=>x.tipo==='despesa').reduce((s,x)=>s+x.valor,0));$('#histList').innerHTML=list.length?list.map(t=>`<div data-edit="${t.id}">${rowHtml(t)}</div>`).join(''):'<div class="empty">Nenhum lançamento encontrado</div>';$$('[data-edit]').forEach(r=>r.onclick=()=>editTransaction(Number(r.dataset.edit)))}
